SELECT no_plan();
SELECT is(partner_private.calculate(100000,300),3000::bigint,'Bronze uses 3% eligible net only');
SELECT is(partner_private.calculate(12345,600),740::bigint,'commission rounds down to integer cents');
SELECT is(partner_private.calculate(0,500),0::bigint,'zero retained rental earns zero');
SELECT ok(NOT (get_partner_program()->>'thresholds_active')::boolean,'draft tier thresholds disabled at launch');
SELECT ok(NOT has_table_privilege('anon','public.partners','select'),'anonymous cannot read applications');
SELECT ok(NOT has_table_privilege('authenticated','public.partner_referrals','select'),'partners cannot query raw referrals');
SELECT ok(NOT has_function_privilege('anon','public.admin_partner_data()','execute'),'anonymous cannot access admin RPC');
CREATE TEMP TABLE partner_fixture(bid uuid,pid uuid,renter uuid,partner_user uuid,admin uuid,source_hash text);
DO $$ DECLARE b bookings; puser uuid; adm uuid; p uuid; BEGIN
 SELECT * INTO b FROM bookings WHERE reservation_number='SYNTHETIC-ACCEPTED';
 SELECT user_id INTO puser FROM profiles WHERE NOT is_admin AND id<>b.renter_profile_id AND id<>b.host_profile_id ORDER BY created_at LIMIT 1;
 SELECT user_id INTO adm FROM profiles WHERE is_admin LIMIT 1;
 UPDATE auth.users SET email_confirmed_at=now() WHERE id=puser;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',puser,'role','authenticated')::text,true);
 p:=apply_partner('Synthetic Partner','Synthetic Hotel','Hotel concierge','3055550101','https://example.invalid');
 INSERT INTO partner_fixture VALUES(b.id,p,(SELECT user_id FROM profiles WHERE id=b.renter_profile_id),puser,adm,md5(to_jsonb(b)::text));
END $$;
SELECT is((get_partner_dashboard()#>>'{partner,status}'),'pending','application begins pending');
SELECT throws_like('SELECT admin_partner_data()','%Admin access required%','partner cannot call admin API');
SELECT ok(NOT (validate_partner_code('FAKECODE')->>'valid')::boolean,'unknown code rejected');
DO $$ BEGIN PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT admin FROM partner_fixture),'role','authenticated')::text,true);PERFORM admin_partner_action('status',(SELECT pid FROM partner_fixture),'{"status":"approved"}');END $$;
SELECT ok((SELECT referral_code IS NOT NULL AND status='approved' FROM partners WHERE id=(SELECT pid FROM partner_fixture)),'approval issues unique code');
DO $$ BEGIN
 UPDATE bookings SET trip_status='pending_payment',created_at=now()-interval '1 hour' WHERE id=(SELECT bid FROM partner_fixture);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT renter FROM partner_fixture),'role','authenticated')::text,true);
END $$;
SELECT lives_ok('SELECT attach_partner_referral((SELECT bid FROM partner_fixture),(SELECT referral_code FROM partners WHERE id=(SELECT pid FROM partner_fixture)),''link'')','renter attributes own pending booking');
SELECT lives_ok('SELECT attach_partner_referral((SELECT bid FROM partner_fixture),(SELECT referral_code FROM partners WHERE id=(SELECT pid FROM partner_fixture)),''link'')','same attribution is idempotent');
SELECT is((SELECT count(*) FROM partner_referrals),1::bigint,'one referral per booking');
SELECT is((get_partner_dashboard()->>'partner'),NULL,'renter cannot inspect partner account');
DO $$ BEGIN PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT partner_user FROM partner_fixture),'role','authenticated')::text,true);END $$;
SELECT throws_like('SELECT attach_partner_referral((SELECT bid FROM partner_fixture),(SELECT referral_code FROM partners LIMIT 1))','%Booking access denied%','other user cannot attribute a renter booking');
SELECT ok(NOT ((get_partner_dashboard()->'bookings'->0)?'email'),'partner booking projection omits renter email');
DO $$ BEGIN PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT admin FROM partner_fixture),'role','authenticated')::text,true);UPDATE bookings SET trip_status='confirmed' WHERE id=(SELECT bid FROM partner_fixture);END $$;
SELECT is((SELECT rate_bps FROM partner_referrals LIMIT 1),300,'rate snapshot at confirmation');
SELECT throws_like('SELECT attach_partner_referral((SELECT bid FROM partner_fixture),(SELECT referral_code FROM partners LIMIT 1))','%locked%','confirmed attribution cannot change');
DO $$ BEGIN PERFORM admin_partner_action('settings',null,'{"silver":1,"gold":2,"platinum":3,"reconciliation_days":14,"thresholds_active":true}');END $$;
SELECT is((SELECT rate_bps FROM partner_referrals LIMIT 1),300,'configuration edits do not change historical rate');
SELECT throws_like($q$SELECT admin_partner_action('verify',(SELECT bid FROM partner_fixture),jsonb_build_object('net_cents',9000,'settled_at',now(),'reference','evidence-test','reason','Synthetic verification','settlement_verified',true,'exclusions_verified',true,'request_id',gen_random_uuid()))$q$,'%Rental must be completed%','active rentals cannot earn');
DO $$ BEGIN UPDATE bookings SET trip_status='completed',returned_at=now() WHERE id=(SELECT bid FROM partner_fixture);END $$;
SELECT throws_like($q$SELECT admin_partner_action('verify',(SELECT bid FROM partner_fixture),jsonb_build_object('net_cents',9000,'settled_at',now(),'reference','evidence-test','reason','Synthetic verification','settlement_verified',true,'exclusions_verified',true,'request_id',gen_random_uuid()))$q$,'%LIVE rental payment%','unpaid rental cannot earn');
DO $$ BEGIN
 INSERT INTO booking_payments(booking_id,agreement_id,provider,environment,amount_cents,currency,state,paid_at) SELECT b.id,a.id,'square','live',b.grand_total_cents,'usd','paid',now() FROM bookings b JOIN booking_rental_agreements a ON a.booking_id=b.id WHERE b.id=(SELECT bid FROM partner_fixture);
END $$;
SELECT lives_ok($q$SELECT admin_partner_action('verify',(SELECT bid FROM partner_fixture),jsonb_build_object('net_cents',9000,'settled_at',now(),'reference','evidence-test','reason','Synthetic final reconciliation','settlement_verified',true,'exclusions_verified',true,'request_id',gen_random_uuid()))$q$,'settled completed rental commission verified');
SELECT is((SELECT commission_cents FROM partner_commissions LIMIT 1),270::bigint,'only net 9000 cents earns 270 cents');
SELECT throws_like($q$SELECT admin_partner_action('pay',(SELECT bid FROM partner_fixture),jsonb_build_object('amount_cents',270,'reference','transfer-test','reason','Synthetic manual transfer','request_id',gen_random_uuid()))$q$,'%not payable%','reconciliation window prevents payout');
SELECT throws_like($q$SELECT admin_partner_action('verify',(SELECT bid FROM partner_fixture),jsonb_build_object('net_cents',100000,'settled_at',now(),'reference','evidence-test','reason','Synthetic final reconciliation','settlement_verified',true,'exclusions_verified',true,'request_id',gen_random_uuid()))$q$,'%Invalid net%','eligible amount cannot exceed net rental subtotal');
DO $$ BEGIN UPDATE partner_commissions SET payable_at=now()-interval '1 hour';END $$;
SELECT lives_ok($q$SELECT admin_partner_action('pay',(SELECT bid FROM partner_fixture),jsonb_build_object('amount_cents',270,'reference','transfer-test','reason','Synthetic manual transfer','request_id',gen_random_uuid()))$q$,'manual paid ledger entry records without provider transaction');
SELECT throws_like($q$SELECT admin_partner_action('pay',(SELECT bid FROM partner_fixture),jsonb_build_object('amount_cents',270,'reference','transfer-test-2','reason','Synthetic manual transfer','request_id',gen_random_uuid()))$q$,'%exceeds%','duplicate payment cannot exceed commission balance');
SELECT lives_ok($q$SELECT admin_partner_action('verify',(SELECT bid FROM partner_fixture),jsonb_build_object('net_cents',5000,'settled_at',now(),'reference','refund-test','reason','Synthetic partial refund reconciliation','settlement_verified',true,'exclusions_verified',true,'request_id',gen_random_uuid()))$q$,'partial refund recomputes commission with signed adjustment');
SELECT is((SELECT sum(CASE WHEN event_type='paid' THEN -amount_cents ELSE amount_cents END) FROM partner_commission_ledger),-120::numeric,'overpaid refunded commission becomes recovery balance');
SELECT ok((SELECT count(*)=1 FROM partner_commission_ledger WHERE event_type='paid'),'prior payout record is preserved');
DO $$ BEGIN UPDATE booking_payments SET state='reconciliation_required' WHERE booking_id=(SELECT bid FROM partner_fixture);END $$;
SELECT is((partner_private.booking_report()#>>'{0,state}'),'review_required','changed financial source invalidates settlement verification');
SELECT is((SELECT count(*) FROM partner_audit WHERE action='application'),1::bigint,'application audit exists');

DO $$ DECLARE partner_profile uuid;b bookings;newid uuid; BEGIN
 SELECT id INTO partner_profile FROM profiles WHERE user_id=(SELECT partner_user FROM partner_fixture);
 SELECT * INTO b FROM bookings WHERE id=(SELECT bid FROM partner_fixture);
 INSERT INTO bookings(reservation_number,renter_profile_id,host_profile_id,vehicle_id,start_date,end_date,pickup_time,dropoff_time,trip_status,subtotal_cents,grand_total_cents) VALUES('SYNTHETIC-SELF',partner_profile,b.host_profile_id,b.vehicle_id,b.start_date,b.end_date,'10:00','10:00','pending_payment',10000,10000) RETURNING id INTO newid;
 PERFORM set_config('partner_test.self',newid::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',(SELECT partner_user FROM partner_fixture),'role','authenticated')::text,true);
END $$;
SELECT throws_like('SELECT attach_partner_referral(current_setting(''partner_test.self'')::uuid,(SELECT referral_code FROM partners LIMIT 1))','%Self-referrals%','self-referral explicitly rejected');
SET LOCAL ROLE authenticated;
SELECT lives_ok('SELECT get_partner_dashboard()','approved partner RPC works with real authenticated role');
SELECT throws_like('SELECT * FROM partners','%permission denied%','raw partner data denied to authenticated role');
RESET ROLE;
SAVEPOINT partner_recovery;
DROP TRIGGER partner_snapshot_after_confirmation ON public.bookings;
REVOKE EXECUTE ON FUNCTION public.apply_partner(text,text,text,text,text),public.attach_partner_referral(uuid,text,text),public.admin_partner_action(text,uuid,jsonb) FROM authenticated;
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='partner_snapshot_after_confirmation'),'recovery isolates booking confirmation from partner subsystem');
SELECT ok(EXISTS(SELECT 1 FROM partner_commission_ledger),'recovery preserves payout history');
ROLLBACK TO SAVEPOINT partner_recovery;
SELECT ok(EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='partner_snapshot_after_confirmation'),'recovery test rolls back cleanly');
